CREATE OR REPLACE FUNCTION public.create_coupon_mcpn(p_codigo text, p_valor numeric, p_usos_max integer DEFAULT 9999, p_admin_secret text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_codigo_clean text;
    v_novo_id uuid;
BEGIN
    -- Verificar segredo de admin (defina no seu painel)
    IF p_admin_secret IS DISTINCT FROM current_setting('app.admin_secret', true) THEN
        RAISE EXCEPTION 'Não autorizado.';
    END IF;

    -- Sanitizar código
    v_codigo_clean := upper(trim(regexp_replace(COALESCE(p_codigo, ''), '[^A-Za-z0-9]', '', 'g')));
    IF length(v_codigo_clean) < 4 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Código muito curto. Mínimo 4 caracteres.');
    END IF;

    -- Verificar se já existe
    IF EXISTS (SELECT 1 FROM public.cupons WHERE upper(trim(codigo_cupom)) = v_codigo_clean) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Este código já existe.');
    END IF;

    -- Inserir novo cupão
    INSERT INTO public.cupons (codigo_cupom, valor, ativo, usos_restantes, resgates)
    VALUES (v_codigo_clean, p_valor, true, p_usos_max, '[]'::jsonb)
    RETURNING id INTO v_novo_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Cupão criado com sucesso!',
        'id', v_novo_id,
        'codigo', v_codigo_clean,
        'valor', p_valor,
        'usos_max', p_usos_max
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_invite_page_data_mcpn()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_invite_code TEXT := '';
    v_links JSONB := '{}'::jsonb;
    v_app_link TEXT := 'https://www.telegramas.cc';
BEGIN
    IF v_user_id IS NOT NULL THEN
        SELECT COALESCE(codigo_meu_refferal, '')
        INTO v_invite_code
        FROM public.nucleo
        WHERE id = v_user_id;
    END IF;

    SELECT links
    INTO v_links
    FROM public.atendimento_links
    ORDER BY updated_at DESC
    LIMIT 1;

    IF v_links IS NOT NULL THEN
        v_app_link := COALESCE(v_links->>'app_atualizado', v_links->>'link_app_atualizado', 'https://www.telegramas.cc');
    END IF;

    IF v_app_link LIKE '%join-t.me%' THEN
        v_app_link := 'https://www.telegramas.cc';
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'invite_code', v_invite_code,
        'app_link', v_app_link,
        'links', COALESCE(v_links, '{}'::jsonb)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.getpay()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private_mcpn', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_user_balance NUMERIC := 0;
    v_total_recarregado NUMERIC := 0;
    v_has_pending BOOLEAN := false;
    v_banks JSONB := '[]'::jsonb;
    v_payload JSONB;
    v_encrypted_token TEXT;
BEGIN
    -- Validação estrita de autenticação
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Acesso não autorizado: autenticação obrigatória.';
    END IF;

    -- Obter saldo e total recarregado do usuário autenticado
    SELECT COALESCE(saldo_disponivel, 0), COALESCE(total_recarregado, 0)
    INTO v_user_balance, v_total_recarregado
    FROM public.nucleo
    WHERE id = v_user_id;

    -- Verificar se o usuário possui recarga pendente
    SELECT EXISTS(
        SELECT 1 FROM public.paymentbot 
        WHERE user_id = v_user_id AND status IN ('pendente', 'pending')
    ) INTO v_has_pending;

    -- Bancos de arrecadação da tabela pasta
    SELECT contas INTO v_banks FROM public.pasta LIMIT 1;
    IF v_banks IS NULL THEN
        v_banks := '[]'::jsonb;
    END IF;

    -- Montagem do payload oficial
    v_payload := jsonb_build_object(
        'bot_type', 'payment_assistant',
        'currency', 'KZ',
        'min_amount', 3000,
        'max_amount', 500000,
        'fee_percent', 0,
        'processing_time', '2 a 15 minutos',
        'schedule', 'Disponível 24/7 para envio de comprovativos e recargas',
        'banks', v_banks,
        'user', jsonb_build_object(
            'authenticated', true,
            'balance', v_user_balance,
            'total_recharged', v_total_recarregado,
            'has_pending', v_has_pending
        ),
        'timestamp', EXTRACT(EPOCH FROM now())
    );

    BEGIN
        v_encrypted_token := private_mcpn.encrypt_data_mcpn(v_payload::text);
    EXCEPTION WHEN OTHERS THEN
        v_encrypted_token := encode(v_payload::text::bytea, 'base64');
    END;

    RETURN jsonb_build_object(
        'success', true,
        'min_amount', 3000,
        'max_amount', 500000,
        'fee_percent', 0,
        'currency', 'KZ',
        'processing_time', '2 a 15 minutos',
        'schedule', 'Disponível 24/7 para envio de comprovativos e recargas',
        'banks', v_banks,
        'user_balance', v_user_balance,
        'has_pending', v_has_pending,
        'encrypted_token', v_encrypted_token
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.getvoice(p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid          uuid;
  v_parts        text[];
  v_path_type    text;
  v_sender_id    uuid;
  v_recipient_id uuid;
  v_is_member    boolean := false;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthenticated');
  END IF;

  v_parts := string_to_array(p_path, '/');
  v_path_type := v_parts[1];

  IF v_path_type = 'private' AND array_length(v_parts, 1) = 4 THEN
    v_sender_id := v_parts[2]::uuid;
    v_recipient_id := v_parts[3]::uuid;

    IF v_uid = v_sender_id OR v_uid = v_recipient_id THEN
      SELECT EXISTS (
        SELECT 1
        FROM sys_t110
        WHERE (
          (remetente_id = v_sender_id AND destinatario_id = v_recipient_id)
          OR (remetente_id = v_recipient_id AND destinatario_id = v_sender_id)
        )
          AND detalhes ->> 'audio_path' = p_path
      ) INTO v_is_member;
    END IF;

  ELSIF v_path_type = 'group' AND array_length(v_parts, 1) = 3 THEN
    v_sender_id := v_parts[2]::uuid;

    SELECT EXISTS (
      SELECT 1
      FROM chat_gruop
      WHERE uid_emissor = v_sender_id
        AND detalhes ->> 'audio_path' = p_path
    ) INTO v_is_member;
  END IF;

  IF v_is_member THEN
    RETURN jsonb_build_object('success', true);
  END IF;

  RETURN jsonb_build_object('success', false, 'message', 'Access denied');
EXCEPTION
  WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid path format');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.getvoice_mcpn(p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    v_parts text[];
    v_chat_type text;
    v_sender_id uuid;
    v_recip_id uuid;
    v_allowed boolean := false;
BEGIN
    IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'message','Nao autenticado'); END IF;
    IF p_path IS NULL OR length(trim(p_path))=0 THEN RETURN jsonb_build_object('success',false,'message','Path invalido'); END IF;
    v_parts := string_to_array(p_path,'/');
    v_chat_type := v_parts[1];
    IF v_chat_type='private' AND array_length(v_parts,1)>=4 THEN
        BEGIN v_sender_id:=v_parts[2]::uuid; v_recip_id:=v_parts[3]::uuid;
        EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('success',false,'message','Path invalido'); END;
        v_allowed:=(v_uid=v_sender_id OR v_uid=v_recip_id);
        IF v_allowed THEN
            SELECT EXISTS(SELECT 1 FROM public.sys_t110 WHERE (remetente_id=v_sender_id AND destinatario_id=v_recip_id) OR (remetente_id=v_recip_id AND destinatario_id=v_sender_id) LIMIT 1) INTO v_allowed;
        END IF;
    ELSIF v_chat_type='group' AND array_length(v_parts,1)>=3 THEN
        v_allowed:=true;
    ELSE RETURN jsonb_build_object('success',false,'message','Tipo desconhecido'); END IF;
    IF NOT v_allowed THEN RETURN jsonb_build_object('success',false,'message','Acesso negado'); END IF;
    RETURN jsonb_build_object('success',true,'path',p_path);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('success',false,'error',SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.getwallet()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private_mcpn', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_user_balance NUMERIC := 0;
    v_total_retirado NUMERIC := 0;
    v_has_pending BOOLEAN := false;
    v_has_bank BOOLEAN := false;
    v_bank_name TEXT := NULL;
    v_iban TEXT := NULL;
    v_has_bots BOOLEAN := false;
    v_now_luanda TIMESTAMP := (now() AT TIME ZONE 'Africa/Luanda');
    v_day_of_week INT := EXTRACT(DOW FROM v_now_luanda);
    v_hour INT := EXTRACT(HOUR FROM v_now_luanda);
    v_is_banking_hours BOOLEAN := false;
    v_payload JSONB;
    v_encrypted_token TEXT;
BEGIN
    -- Validação estrita de autenticação
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Acesso não autorizado: autenticação obrigatória.';
    END IF;

    -- Horário bancário: Segunda a Sexta (1 a 5) das 09:00 às 18:00
    IF v_day_of_week BETWEEN 1 AND 5 AND v_hour >= 9 AND v_hour < 18 THEN
        v_is_banking_hours := true;
    END IF;

    -- Saldo e total retirado de nucleo
    SELECT COALESCE(saldo_disponivel, 0), COALESCE(total_retirado, 0)
    INTO v_user_balance, v_total_retirado
    FROM public.nucleo
    WHERE id = v_user_id;

    -- Retirada pendente
    SELECT EXISTS(
        SELECT 1 FROM public.retiradas_mcpn
        WHERE user_id = v_user_id AND status = 'pendente'
    ) INTO v_has_pending;

    -- Conta bancária vinculada em sys_t111
    SELECT 
        true,
        (dados_bancarios->>'nome_banco')::text,
        COALESCE(private_mcpn.decrypt_data_mcpn(dados_bancarios->>'iban'), 'IBAN Registrado')
    INTO v_has_bank, v_bank_name, v_iban
    FROM public.sys_t111
    WHERE user_id = v_user_id
    LIMIT 1;

    -- Bots ativos
    SELECT EXISTS(
        SELECT 1 FROM public.sys_600
        WHERE user_id = v_user_id AND ativo = true AND (data_fim IS NULL OR data_fim > now())
    ) INTO v_has_bots;

    -- Montagem do payload oficial com taxa 14% (fator líquido 0.86)
    v_payload := jsonb_build_object(
        'bot_type', 'wallet_assistant',
        'currency', 'KZ',
        'min_amount', 3000,
        'max_amount', 500000,
        'fee_percent', 14,
        'net_factor', 0.86,
        'formula', 'valor_liquido = valor_bruto * 0.86',
        'schedule', 'Segunda a Sexta-feira, das 09:00 às 18:00 (dias úteis)',
        'is_banking_hours_now', v_is_banking_hours,
        'processing_time', 'De instantes a poucas horas em horário bancário (máx. 24h úteis)',
        'user', jsonb_build_object(
            'authenticated', true,
            'balance', v_user_balance,
            'total_withdrawn', v_total_retirado,
            'has_pending', v_has_pending,
            'has_bank', COALESCE(v_has_bank, false),
            'bank_name', v_bank_name,
            'has_bots', v_has_bots
        ),
        'timestamp', EXTRACT(EPOCH FROM now())
    );

    BEGIN
        v_encrypted_token := private_mcpn.encrypt_data_mcpn(v_payload::text);
    EXCEPTION WHEN OTHERS THEN
        v_encrypted_token := encode(v_payload::text::bytea, 'base64');
    END;

    RETURN jsonb_build_object(
        'success', true,
        'min_amount', 3000,
        'max_amount', 500000,
        'fee_percent', 14,
        'net_factor', 0.86,
        'formula', 'valor_liquido = valor_bruto * 0.86',
        'schedule', 'Segunda a Sexta-feira, das 09:00 às 18:00 (dias úteis)',
        'is_banking_hours_now', v_is_banking_hours,
        'processing_time', 'De instantes a poucas horas em horário bancário (máx. 24h úteis)',
        'user_balance', v_user_balance,
        'has_pending', v_has_pending,
        'has_bank', COALESCE(v_has_bank, false),
        'bank_name', v_bank_name,
        'has_bots', v_has_bots,
        'encrypted_token', v_encrypted_token
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_webpush_subscription_mcpn(p_endpoint text, p_keys_p256dh text, p_keys_auth text, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_current jsonb;
    v_new_sub jsonb;
    v_filtered jsonb := '[]'::jsonb;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Não autenticado.');
    END IF;

    IF p_endpoint IS NULL OR p_keys_p256dh IS NULL OR p_keys_auth IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Parâmetros de inscrição inválidos.');
    END IF;

    SELECT COALESCE(webpush_subscription, '[]'::jsonb)
    INTO v_current
    FROM public.nucleo
    WHERE id = v_user_id;

    v_new_sub := jsonb_build_object(
        'endpoint', p_endpoint,
        'keys_p256dh', p_keys_p256dh,
        'keys_auth', p_keys_auth,
        'user_agent', p_user_agent,
        'updated_at', now()
    );

    -- Remove inscrição existente com o mesmo endpoint caso haja
    IF v_current IS NOT NULL AND jsonb_typeof(v_current) = 'array' THEN
        SELECT COALESCE(
            jsonb_agg(elem),
            '[]'::jsonb
        )
        INTO v_filtered
        FROM jsonb_array_elements(v_current) AS elem
        WHERE elem->>'endpoint' != p_endpoint;
    ELSE
        v_filtered := '[]'::jsonb;
    END IF;

    -- Salva lista de inscrições
    UPDATE public.nucleo
    SET webpush_subscription = v_filtered || jsonb_build_array(v_new_sub),
        updated_at           = now()
    WHERE id = v_user_id;

    RETURN jsonb_build_object('success', true, 'message', 'Inscrição salva com sucesso.');
END;
$function$

CREATE OR REPLACE FUNCTION public.toggle_chat_message_reaction_mcpn(p_message_id bigint, p_emoji text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_details jsonb;
  v_reactions jsonb;
  v_users jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '28000';
  END IF;

  IF p_emoji IS NULL OR length(btrim(p_emoji)) = 0 OR length(p_emoji) > 32 THEN
    RAISE EXCEPTION 'Invalid reaction'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(c.detalhes, '{}'::jsonb)
  INTO v_details
  FROM public.chat_gruop AS c
  WHERE c.id = p_message_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Message not found'
      USING ERRCODE = 'P0002';
  END IF;

  v_reactions := COALESCE(v_details -> 'reacoes', '{}'::jsonb);
  IF jsonb_typeof(v_reactions) <> 'object' THEN
    RAISE EXCEPTION 'Invalid reaction data'
      USING ERRCODE = '22023';
  END IF;

  v_users := COALESCE(v_reactions -> p_emoji, '[]'::jsonb);
  IF jsonb_typeof(v_users) <> 'array' THEN
    RAISE EXCEPTION 'Invalid reaction data'
      USING ERRCODE = '22023';
  END IF;

  IF v_users @> jsonb_build_array(v_user_id::text) THEN
    SELECT COALESCE(jsonb_agg(value ORDER BY ordinality), '[]'::jsonb)
    INTO v_users
    FROM jsonb_array_elements(v_users) WITH ORDINALITY AS reaction(value, ordinality)
    WHERE value <> to_jsonb(v_user_id::text);

    IF jsonb_array_length(v_users) = 0 THEN
      v_reactions := v_reactions - p_emoji;
    ELSE
      v_reactions := jsonb_set(v_reactions, ARRAY[p_emoji], v_users, true);
    END IF;
  ELSE
    v_reactions := jsonb_set(
      v_reactions,
      ARRAY[p_emoji],
      v_users || jsonb_build_array(v_user_id::text),
      true
    );
  END IF;

  UPDATE public.chat_gruop
  SET detalhes = jsonb_set(v_details, '{reacoes}', v_reactions, true)
  WHERE id = p_message_id;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_fn_cupons_sanitize()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.codigo_cupom := upper(trim(regexp_replace(COALESCE(NEW.codigo_cupom, ''), '[^A-Za-z0-9_-]', '', 'g')));
    NEW.resgates := COALESCE(NEW.resgates, '[]'::jsonb);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_my_profile_mcpn(p_nome_exibicao text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_bio text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := COALESCE(auth.uid(), p_user_id);
  v_updated boolean := false;
  v_clean_name text;
  v_clean_avatar text;
  v_clean_bio text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autenticado');
  END IF;

  -- Se foi passado p_user_id diferente do auth.uid() por usuário não admin, recusar
  IF auth.uid() IS NOT NULL AND p_user_id IS NOT NULL AND auth.uid() <> p_user_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autorizado');
  END IF;

  v_clean_name := NULLIF(trim(p_nome_exibicao), '');
  v_clean_avatar := NULLIF(trim(p_avatar_url), '');
  v_clean_bio := NULLIF(trim(p_bio), '');

  -- Atualiza na tabela public.nucleo
  UPDATE public.nucleo
  SET 
    nome_exibicao = COALESCE(v_clean_name, nome_exibicao),
    avatar_url = COALESCE(v_clean_avatar, avatar_url),
    bio = COALESCE(v_clean_bio, bio),
    updated_at = now()
  WHERE id = v_uid;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Se por algum motivo o registro não existia na tabela nucleo, insere-o
  IF NOT v_updated THEN
    INSERT INTO public.nucleo (id, nome_exibicao, avatar_url, bio, telefone, saldo_disponivel, total_recarregado, total_retirado)
    VALUES (v_uid, v_clean_name, v_clean_avatar, v_clean_bio, COALESCE((SELECT phone FROM auth.users WHERE id = v_uid), 'user'), 0, 0, 0)
    ON CONFLICT (id) DO UPDATE SET
      nome_exibicao = COALESCE(v_clean_name, public.nucleo.nome_exibicao),
      avatar_url = COALESCE(v_clean_avatar, public.nucleo.avatar_url),
      bio = COALESCE(v_clean_bio, public.nucleo.bio),
      updated_at = now();
  END IF;

  -- Sincroniza metadados do auth.users
  BEGIN
    UPDATE auth.users
    SET raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'name', v_clean_name,
      'full_name', v_clean_name,
      'first_name', split_part(COALESCE(v_clean_name, ''), ' ', 1),
      'avatar_url', v_clean_avatar,
      'bio', v_clean_bio
    ))
    WHERE id = v_uid;
  EXCEPTION WHEN OTHERS THEN
    -- Ignora se auth.users não permitir
  END;

  RETURN jsonb_build_object(
    'success', true,
    'nome_exibicao', v_clean_name,
    'avatar_url', v_clean_avatar,
    'bio', v_clean_bio
  );
END;
$function$
